                    const percent = Math.min(100, Math.round((item.value / item.max) * 100));
                    return (
                        <Flex key={item.name} direction="column" gap={1}>
                            <Flex justifyContent="space-between" gap={2}>
                                <Text variant="body-1" ellipsis style={{flex: 1, minWidth: 0}}>
                                    {item.name}
