                            </Flex>
                            <Progress
                                size="s"
                                value={percent}
                                colorStops={[
                                    {theme: 'info', stop: 70},
                                    {theme: 'warning', stop: 90},
                                    {theme: 'danger', stop: 100},
                                ]}
